<?= $this->extend('layout') ?><?= $this->section('content') ?><section class="card"><p class="eyebrow">Task management</p><h1><?= esc($title) ?></h1><?php $errors=session()->getFlashdata('errors')??[]; if($errors): ?><div class="alert error"><ul><?php foreach($errors as $e): ?><li><?= esc($e) ?></li><?php endforeach; ?></ul></div><?php endif; ?><form action="<?= esc($action) ?>" method="post"><?= csrf_field() ?><label>Title *</label><input name="title" value="<?= esc(old('title',$task['title']??'')) ?>" maxlength="150" required><label>Task date *</label><input type="date" name="task_date" value="<?= esc(old('task_date',$task['task_date']??date('Y-m-d'))) ?>" required><label>Status</label><?php $status=old('status',$task['status']??'pending'); ?><select name="status"><option value="pending" <?= $status==='pending'?'selected':'' ?>>Pending</option><option value="completed" <?= $status==='completed'?'selected':'' ?>>Completed</option></select><div class="form-actions"><button class="button">Save Task</button><a class="button secondary" href="<?= site_url('tasks') ?>">Cancel</a></div></form></section><?= $this->endSection() ?>
